using System;
using System.IO;
using System.Data;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

namespace DataImport.Driver
{
    public sealed class BulkImportOptions
    {
        public string ConnectionString { get; set; }
        public string TargetTable { get; set; }
        public int BatchSize { get; set; } = 1000;
        public TimeSpan Timeout { get; set; } = TimeSpan.FromMinutes(5);
    }

    public sealed class SecureFileHandle : IDisposable
    {
        public string FilePath { get; }
        private bool _disposed;

        public SecureFileHandle(string directory, string prefix)
        {
            // Generate cryptographically random filename component
            var randomBytes = new byte[16];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(randomBytes);
            }
            var randomName = BitConverter.ToString(randomBytes).Replace("-", "").ToLowerInvariant();
            FilePath = Path.Combine(directory, $"{prefix}_{randomName}.tmp");
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                _disposed = true;
                try { File.Delete(FilePath); } catch { }
            }
        }
    }

    public sealed class ImportStagingManager
    {
        private readonly string _stagingDirectory;
        private readonly object _lock = new object();

        public ImportStagingManager(string stagingDirectory)
        {
            _stagingDirectory = stagingDirectory ?? throw new ArgumentNullException(nameof(stagingDirectory));
            if (!Directory.Exists(_stagingDirectory))
            {
                Directory.CreateDirectory(_stagingDirectory);
            }
        }

        public string GetStagingDirectory() => _stagingDirectory;

        /// <summary>
        /// Creates a staging file for the upload with proper isolation.
        /// The caller is responsible for cleanup via the returned handle.
        /// </summary>
        public SecureFileHandle CreateStagingFile(string sessionId)
        {
            if (string.IsNullOrWhiteSpace(sessionId))
                throw new ArgumentException("Session ID required", nameof(sessionId));

            // Validate session ID format (alphanumeric + hyphens only)
            foreach (char c in sessionId)
            {
                if (!char.IsLetterOrDigit(c) && c != '-')
                    throw new ArgumentException("Invalid session ID format", nameof(sessionId));
            }

            return new SecureFileHandle(_stagingDirectory, $"import_{sessionId}");
        }
    }

    public sealed class BulkDataImporter
    {
        private readonly BulkImportOptions _options;
        private readonly ImportStagingManager _stagingManager;

        public BulkDataImporter(BulkImportOptions options, ImportStagingManager stagingManager)
        {
            _options = options ?? throw new ArgumentNullException(nameof(options));
            _stagingManager = stagingManager ?? throw new ArgumentNullException(nameof(stagingManager));
        }

        /// <summary>
        /// Processes an uploaded CSV stream by staging it to disk, validating,
        /// then bulk-inserting into the target database table.
        /// </summary>
        public async Task<int> ProcessUploadAsync(Stream uploadStream, string sessionId)
        {
            if (uploadStream == null) throw new ArgumentNullException(nameof(uploadStream));

            using var stagingFile = _stagingManager.CreateStagingFile(sessionId);

            // Stage the upload to a temporary file for processing
            await WriteToStagingFileAsync(uploadStream, stagingFile.FilePath);

            // Validate and transform the staged data
            var validatedPath = await ValidateAndTransformAsync(stagingFile.FilePath, sessionId);

            try
            {
                // Bulk insert the validated data
                return await BulkInsertAsync(validatedPath);
            }
            finally
            {
                try { File.Delete(validatedPath); } catch { }
            }
        }

        private async Task WriteToStagingFileAsync(Stream source, string targetPath)
        {
            using var fileStream = new FileStream(
                targetPath,
                FileMode.CreateNew,
                FileAccess.Write,
                FileShare.None,
                bufferSize: 81920,
                useAsync: true);

            await source.CopyToAsync(fileStream);
            await fileStream.FlushAsync();
        }

        private async Task<string> ValidateAndTransformAsync(string sourcePath, string sessionId)
        {
            // Create a validated output file in the same staging directory
            var validatedFileName = $"validated_{sessionId}_{Environment.TickCount}.tmp";
            var validatedPath = Path.Combine(_stagingManager.GetStagingDirectory(), validatedFileName);

            using var reader = new StreamReader(sourcePath);
            using var writer = new StreamWriter(validatedPath);

            string line;
            int lineNumber = 0;
            while ((line = await reader.ReadLineAsync()) != null)
            {
                lineNumber++;
                if (lineNumber == 1) continue; // Skip header

                var fields = line.Split(',');
                if (fields.Length < 2)
                    throw new FormatException($"Invalid format at line {lineNumber}");

                // Sanitize fields for SQL safety
                for (int i = 0; i < fields.Length; i++)
                {
                    fields[i] = fields[i].Trim().Replace("'", "''");
                }

                await writer.WriteLineAsync(string.Join("\t", fields));
            }

            return validatedPath;
        }

        private async Task<int> BulkInsertAsync(string dataFilePath)
        {
            using var connection = new SqlConnection(_options.ConnectionString);
            await connection.OpenAsync();

            using var bulkCopy = new SqlBulkCopy(connection)
            {
                DestinationTableName = _options.TargetTable,
                BatchSize = _options.BatchSize,
                BulkCopyTimeout = (int)_options.Timeout.TotalSeconds
            };

            // Use a DataTable loaded from the validated file
            var dataTable = await LoadDataTableAsync(dataFilePath);
            await bulkCopy.WriteToServerAsync(dataTable);

            return dataTable.Rows.Count;
        }

        private async Task<DataTable> LoadDataTableAsync(string filePath)
        {
            var dt = new DataTable();
            dt.Columns.Add("Col1", typeof(string));
            dt.Columns.Add("Col2", typeof(string));

            using var reader = new StreamReader(filePath);
            string line;
            while ((line = await reader.ReadLineAsync()) != null)
            {
                var parts = line.Split('\t');
                if (parts.Length >= 2)
                {
                    dt.Rows.Add(parts[0], parts[1]);
                }
            }

            return dt;
        }
    }
}
